var automatisch,
  Morgenlicht_Arbeit,
  Morgenlicht_HO,
  timeout,
  timeout1,
  timeout4,
  Triggersperre,
  timeout3,
  timeout2;

// In bestimmten Situationen wird die Variable automatisch nicht auf wahr gesetzt.
schedule("59 4 * * *", async () => {
  if (!automatisch) {
    automatisch = true;
  }
});
setState("sonoff.0.Garderobenlicht.POWER" /* Garderobenlicht POWER */, false);
automatisch = true;
Morgenlicht_Arbeit = false;
Morgenlicht_HO = false;
// Prüfung ob Licht automatisch oder manuell eingeschaltet wurde
on(
  { id: "sonoff.0.Garderobenlicht.POWER" /* Garderobenlicht POWER */, change: "gt" },
  async (obj) => {
    const value = obj.state.val;
    const oldValue = obj.oldState.val;
    if (
      (obj.state ? obj.state.from : "") == "system.adapter.javascript.0" ||
      (obj.state ? obj.state.from : "") == "system.adapter.iot.0" ||
      (obj.state ? obj.state.from : "") == "system.adapter.hm-rpc.1"
    ) {
      automatisch = true;
    } else if (
      (obj.state ? obj.state.val : "") &&
      (obj.state ? obj.state.from : "") != "system.adapter.javascript.0" &&
      (obj.state ? obj.state.from : "") != "system.adapter.iot.0" &&
      (obj.state ? obj.state.from : "") != "system.adapter.hm-rpc.1"
    ) {
      (() => {
        if (timeout) {
          clearTimeout(timeout);
          timeout = null;
        }
      })();
      (() => {
        if (timeout1) {
          clearTimeout(timeout1);
          timeout1 = null;
        }
      })();
      (() => {
        if (timeout2) {
          clearTimeout(timeout2);
          timeout2 = null;
        }
      })();
      automatisch = false;
    } else if (
      !(obj.state ? obj.state.val : "") &&
      (obj.state ? obj.state.from : "") != "system.adapter.javascript.0" &&
      (obj.state ? obj.state.from : "") != "system.adapter.iot.0" &&
      (obj.state ? obj.state.from : "") != "system.adapter.hm-rpc.1"
    ) {
      (() => {
        if (timeout) {
          clearTimeout(timeout);
          timeout = null;
        }
      })();
      (() => {
        if (timeout1) {
          clearTimeout(timeout1);
          timeout1 = null;
        }
      })();
      (() => {
        if (timeout2) {
          clearTimeout(timeout2);
          timeout2 = null;
        }
      })();
      automatisch = true;
    }
  },
);
// Status des Bewegungsmelders wurde aktualisiert
on(
  { id: [].concat(["hm-rpc.1.000C20C9AF5D1A.1.PRESENCE_DETECTION_STATE"]), change: "any" },
  async (obj) => {
    const value = obj.state.val;
    const oldValue = obj.oldState.val;
    // Das Garderobenlicht wird Mo-Fr in Abhängigkeit von der Eigenschaft Homeoffice oder Dienststelle morgens zu verschiedenen Zeiten und verschiednen Zeiträumen eingeschaltet. In dieser Zeit wird nach Aktivieren des BWM nicht automatisch abgeschaltet, sondern nach Auslösen des BWM erst nach 42 Minuten.
    if (
      automatisch &&
      (obj.state ? obj.state.val : "") &&
      !Morgenlicht_Arbeit &&
      getState("0_userdata.0.Heizen.Programme.standard")?.val &&
      getState("0_userdata.0.Licht.Garderobe.BWM")?.val &&
      (() => {
        const d = new Date().getDay();
        return d === 0 ? 7 : d;
      })() >= "1" &&
      (() => {
        const d = new Date().getDay();
        return d === 0 ? 7 : d;
      })() <= "5" &&
      compareTime("05:18", "06:00", "between", null)
    ) {
      // Dienststelle (die Zustände Homeoffice und Außerhaus und Urlaub sind nicht wahr)
      setState("sonoff.0.Garderobenlicht.POWER" /* Garderobenlicht POWER */, true);
      Morgenlicht_Arbeit = true;
      (() => {
        if (timeout) {
          clearTimeout(timeout);
          timeout = null;
        }
      })();
      timeout = setTimeout(async () => {
        timeout = null;
        setState("sonoff.0.Garderobenlicht.POWER" /* Garderobenlicht POWER */, false);
        Morgenlicht_Arbeit = false;
      }, 3000000);
    } else if (
      automatisch &&
      (obj.state ? obj.state.val : "") &&
      !Morgenlicht_HO &&
      getState("0_userdata.0.Heizen.Programme.Homeoffice")?.val &&
      !getState("0_userdata.0.Heizen.Programme.Zuhause")?.val &&
      getState("0_userdata.0.Licht.Garderobe.BWM")?.val &&
      (() => {
        const d = new Date().getDay();
        return d === 0 ? 7 : d;
      })() >= "1" &&
      (() => {
        const d = new Date().getDay();
        return d === 0 ? 7 : d;
      })() <= "5" &&
      compareTime("05:48", "06:30", "between", null)
    ) {
      // Homeoffice (die Zustände Standard, Außerhaus und Urlaub sind nicht wahr)
      setState("sonoff.0.Garderobenlicht.POWER" /* Garderobenlicht POWER */, true);
      Morgenlicht_HO = true;
      (() => {
        if (timeout1) {
          clearTimeout(timeout1);
          timeout1 = null;
        }
      })();
      timeout1 = setTimeout(async () => {
        timeout1 = null;
        setState("sonoff.0.Garderobenlicht.POWER" /* Garderobenlicht POWER */, false);
        Morgenlicht_HO = false;
      }, 3000000);
    } else if (
      automatisch &&
      true &&
      !Morgenlicht_HO &&
      !Morgenlicht_Arbeit &&
      getState("0_userdata.0.Licht.Garderobe.BWM")?.val
    ) {
      // BWM löst aus und schaltet bei keiner erneuten Änderung nach 120 Sekunden das Licht aus.
      setState("sonoff.0.Garderobenlicht.POWER" /* Garderobenlicht POWER */, true);
      (() => {
        if (timeout2) {
          clearTimeout(timeout2);
          timeout2 = null;
        }
      })();
      timeout4 = setTimeout(async () => {
        timeout4 = null;
        setState("sonoff.0.Garderobenlicht.POWER" /* Garderobenlicht POWER */, false);
      }, 150000);
      // Triggersperre für Ausschalten
    }
  },
);


